document.querySelector("#batch40 .grid").insertAdjacentHTML("beforeend","<a class=\"card\" href=\"summaries/mahmoud-visit.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف زيارة للجنة والنار\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة · غير متاح حاليا</span><h3>زيارة للجنة والنار</h3><p>يثبت المرجع التجاري زيارة للجنة والنار عملا لمصطفى محمود في إصدار مؤسسة أخبار اليوم. لكن الصفحة التي فحصناها تكتفي ببيانات الطبعة وتصنيفات دينية،…</p><small>مصطفى محمود</small></a><a class=\"card\" href=\"summaries/mahmoud-tales.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف حكايات مسافر\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة · غير متاح حاليا</span><h3>حكايات مسافر</h3><p>تعرّف نبذة الطبعة حكايات مسافر بانطباعات مصطفى محمود عن مدن زارها، بينها باريس ولندن وبيروت وطرابلس. وهذا يضع تجربة الكاتب ونظرته في المقدمة، بدل…</p><small>مصطفى محمود</small></a><a class=\"card\" href=\"summaries/paranormal-special9.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف جاءوا من الوادي : الأعداد الخاصة (ما وراء الطبيعة - سفاري - فانتازيا) 9\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>جاءوا من الوادي : الأعداد الخاصة (ما وراء الطبيعة - سفاري - فانتازيا) 9</h3><p>تربط نبذة جاءوا من الوادي عبير بوادي عبقر وعالم الشعر، داخل الأعداد الخاصة المشتركة لما وراء الطبيعة وسفاري وفانتازيا. لذلك لا ننسب المغامرة تلقا…</p><small>أحمد خالد توفيق</small></a>");
